package com.ruoyi.framework.aspect;
import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;import static org.mockito.ArgumentMatchers.*;import java.util.*;import org.springframework.aop.aspectj.annotation.AspectJProxyFactory;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.transaction.PlatformTransactionManager;import org.springframework.transaction.support.SimpleTransactionStatus;import com.ruoyi.metal.security.FactoryScope;import com.ruoyi.system.service.impl.SysRoleServiceImpl;import com.ruoyi.system.service.ISysRoleService;import com.ruoyi.system.mapper.SysUserRoleMapper;import com.ruoyi.system.domain.SysUserRole;
class LegacyRoleSessionTest{
 static class Fixture{FactoryScope scope=mock(FactoryScope.class);JdbcTemplate jdbc=mock(JdbcTemplate.class);PlatformTransactionManager tx=mock(PlatformTransactionManager.class);SysUserRoleMapper mapper=mock(SysUserRoleMapper.class);ISysRoleService service;
  Fixture()throws Exception{when(tx.getTransaction(any())).thenReturn(new SimpleTransactionStatus());when(jdbc.queryForList(anyString(),any(Object[].class))).thenAnswer(a->{String sql=a.getArgument(0);return sql.contains("sys_user_role")?List.of(Map.of("user_id",10L)):List.of(Map.of("user_id",10L,"factory_id",7L));});when(mapper.deleteUserRoleInfo(any())).thenReturn(1);when(mapper.deleteUserRoleInfos(anyLong(),any())).thenReturn(1);when(mapper.batchUserRole(anyList())).thenReturn(1);var target=new SysRoleServiceImpl();var field=SysRoleServiceImpl.class.getDeclaredField("userRoleMapper");field.setAccessible(true);field.set(target,mapper);var aspect=new LegacyIdentityGuard(scope,jdbc);try{var manager=LegacyIdentityGuard.class.getDeclaredField("transactionManager");manager.setAccessible(true);manager.set(aspect,tx);}catch(NoSuchFieldException old){}var proxy=new AspectJProxyFactory(target);proxy.setProxyTargetClass(true);proxy.addAspect(aspect);service=(ISysRoleService)proxy.getProxy();}
 }
 @Test void cancelInvalidatesTheUserAndCommits()throws Exception{var f=new Fixture();var relation=new SysUserRole();relation.setUserId(10L);relation.setRoleId(20L);assertEquals(1,f.service.deleteAuthUser(relation));verify(f.scope).invalidate(Set.of(10L));verify(f.tx).commit(any());}
 @Test void cancelAllDeduplicatesIdsAndNeverInvalidatesRoleId()throws Exception{var f=new Fixture();assertEquals(1,f.service.deleteAuthUsers(20L,new Long[]{10L,10L}));verify(f.scope).invalidate(Set.of(10L));verify(f.scope,never()).invalidate(Set.of(20L));}
 @Test void failedMutationRollsBackWithoutInvalidating()throws Exception{var f=new Fixture();doThrow(new IllegalStateException("fixture failure")).when(f.mapper).deleteUserRoleInfos(anyLong(),any());assertThrows(IllegalStateException.class,()->f.service.deleteAuthUsers(20L,new Long[]{10L}));verify(f.scope,never()).invalidate(anyCollection());verify(f.tx).rollback(any());}
 @Test void grantsApplyFactoryRulesAndInvalidateOnlyNewMembers()throws Exception{var f=new Fixture();when(f.jdbc.queryForList(contains("sys_user_role"),any(Object[].class))).thenReturn(List.of());assertEquals(1,f.service.insertAuthUsers(20L,new Long[]{10L}));verify(f.scope).roleGrants(7L,List.of(20L));verify(f.scope).invalidate(Set.of(10L));}
 @Test void failedGrantAndInvalidArgumentsCannotMutate()throws Exception{var f=new Fixture();doThrow(new com.ruoyi.common.exception.ServiceException("角色必须属于所选工厂",403)).when(f.scope).roleGrants(anyLong(),anyList());assertThrows(com.ruoyi.common.exception.ServiceException.class,()->f.service.insertAuthUsers(20L,new Long[]{10L}));assertThrows(com.ruoyi.common.exception.ServiceException.class,()->f.service.deleteAuthUsers(20L,new Long[]{}));assertThrows(com.ruoyi.common.exception.ServiceException.class,()->f.service.insertAuthUsers(1L,new Long[]{10L}));verify(f.mapper,never()).batchUserRole(anyList());verify(f.scope,never()).invalidate(anyCollection());}
}
